package com.hrm.service;

import com.hrm.dto.OvertimeDTOs.*;
import com.hrm.security.AuthenticatedAccount;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import org.springframework.aop.framework.ProxyFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.support.JdbcTransactionManager;
import org.springframework.transaction.annotation.AnnotationTransactionAttributeSource;
import org.springframework.transaction.interceptor.TransactionInterceptor;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.web.server.ResponseStatusException;

/** Explicit opt-in. All fixture OT, requests, attendance, scopes and audit writes roll back. */
@EnabledIfSystemProperty(named="hrm.overtime.sqlserver-tests",matches="true")
class OvertimeWorkspaceIntegrationTest {
    static JdbcTemplate db;static JdbcTransactionManager manager;static OvertimePermissionService perms;static OvertimeDailyLedger ledger;static OvertimeRecognizedMinutes recognition;static OvertimeService core;static OvertimeRequestWorkflowService workflows;static OvertimeWorkspaceService service;static AuthenticatedAccount admin,hr,employee;static Clock clock;
    static String resolve(String v){if(v!=null&&v.startsWith("${")&&v.endsWith("}")){var p=v.substring(2,v.length()-1).split(":",2);return System.getenv().getOrDefault(p[0],p.length>1?p[1]:"");}return v;}
    @BeforeAll static void setup()throws Exception{
        Properties p=new Properties();var dir=Path.of(System.getProperty("hrm.overtime.test-resource-dir","src/main/resources"));for(String name:List.of("application.properties","application-local.properties"))try(var in=Files.newInputStream(dir.resolve(name))){p.load(in);}
        var ds=new DriverManagerDataSource(resolve(p.getProperty("spring.datasource.url")),resolve(p.getProperty("spring.datasource.username")),resolve(p.getProperty("spring.datasource.password")));db=new JdbcTemplate(ds);manager=new JdbcTransactionManager(ds);clock=Clock.system(ZoneId.of("Asia/Ho_Chi_Minh"));perms=new OvertimePermissionService(db);ledger=new OvertimeDailyLedger(db);recognition=new OvertimeRecognizedMinutes(db);core=proxy(new OvertimeService(db,perms,ledger,recognition));workflows=proxy(new OvertimeRequestWorkflowService(db,perms));service=proxy(new OvertimeWorkspaceService(db,perms,core,workflows,recognition,ledger,clock));admin=principal("ADMIN");hr=principal("HR");employee=principal("EMPLOYEE");
    }
    @SuppressWarnings("unchecked") static <T>T proxy(T target){var f=new ProxyFactory(target);f.setProxyTargetClass(true);f.addAdvice(new TransactionInterceptor(manager,new AnnotationTransactionAttributeSource()));return (T)f.getProxy();}
    static AuthenticatedAccount principal(String role){return db.query("SELECT TOP(1) a.account_id,a.employee_id,a.username,r.role_code FROM dbo.accounts a JOIN dbo.roles r ON r.role_id=a.role_id JOIN dbo.employees e ON e.employee_id=a.employee_id WHERE a.is_active=1 AND r.role_code=? AND e.employment_status='DANG_LAM' ORDER BY a.account_id",(rs,n)->new AuthenticatedAccount(rs.getLong(1),rs.getLong(2),rs.getString(3),rs.getString(4)),role).get(0);}
    void rollback(Runnable r){new TransactionTemplate(manager).executeWithoutResult(status->{try{r.run();}finally{status.setRollbackOnly();}});}
    LocalDate day(int offset){return LocalDate.now(clock).plusDays(offset);}
    Register body(int offset,int start,int end){return new Register(day(offset).atTime(start,0),day(offset).atTime(end,0),"ROLLBACK-ONLY OT test",List.of(),"Công việc kiểm thử");}
    String version(AuthenticatedAccount who,long id){return service.detail(who,id).row().version();}
    void action(AuthenticatedAccount who,long id,String action){service.action(who,id,action,new OvertimeWorkspaceService.Mutation(version(who,id),"Đã kiểm tra",null));}
    void actual(long id,LocalDateTime start,LocalDateTime end){service.action(admin,id,"actual",new OvertimeWorkspaceService.Mutation(version(admin,id),"Giờ đã xác minh",new Actual(start,end,0,List.of(),"Giờ đã xác minh")));}
    void scopeHr(){db.update("INSERT dbo.hr_department_scopes(hr_account_id,department_id,effective_from,created_by) SELECT ?,department_id,DATEADD(day,-10,SYSUTCDATETIME()),? FROM dbo.employee_assignments WHERE employee_id=? AND effective_from<=? AND (effective_to IS NULL OR effective_to>?)",hr.accountId(),admin.accountId(),employee.employeeId(),day(-1),day(-1));}
    OvertimeWorkspaceService.Filter filter(boolean mine){return new OvertimeWorkspaceService.Filter(mine,day(-30),day(30),null,null,null,null,null,null,0);}
    @Test void contextAndReadScopes(){rollback(()->{
        assertFalse(service.context(admin).mine());assertFalse(service.context(admin).canRegister());assertTrue(service.context(hr).canRegister());
        assertThrows(ResponseStatusException.class,()->service.register(admin,body(1,20,21)));
    });rollback(()->{var mine=service.register(hr,body(1,20,21));var employeeOt=service.register(employee,body(1,20,21));assertTrue(service.search(hr,filter(true)).items().stream().allMatch(r->r.ot().employeeId()==hr.employeeId()));assertFalse(service.search(hr,filter(false)).items().stream().anyMatch(r->r.ot().overtimeId()==mine.overtimeId()||r.ot().overtimeId()==employeeOt.overtimeId()));assertThrows(ResponseStatusException.class,()->service.employees(employee,filter(false)));});}
    @Test void groupingIsOneRowPerEmployeeAndDoesNotCountUnconfirmedAsValid(){rollback(()->{service.register(employee,body(1,20,21));service.register(employee,body(2,20,21));var result=service.employees(admin,new OvertimeWorkspaceService.Filter(false,day(1),day(2),null,null,null,null,null,employee.employeeId(),0));assertEquals(1,result.items().size());assertEquals(2,result.items().get(0).requests());assertEquals(0,result.items().get(0).validMinutes());});}
    @Test void hrCannotApproveOwnOt(){rollback(()->{var o=service.register(hr,body(1,20,21));assertThrows(ResponseStatusException.class,()->action(hr,o.overtimeId(),"approve"));});}
    @Test void employeeCannotReadOtherOrApprove(){rollback(()->{var o=service.register(hr,body(1,20,21));assertThrows(ResponseStatusException.class,()->service.detail(employee,o.overtimeId()));});}
    @Test void adminCanApproveHrAndConfirmAsSeparateAuditedStep(){rollback(()->{var o=service.register(hr,body(-1,20,21));action(admin,o.overtimeId(),"approve");actual(o.overtimeId(),o.requestedStart(),o.requestedEnd());action(admin,o.overtimeId(),"confirm");var d=service.detail(admin,o.overtimeId());assertEquals(60L,d.row().validMinutes());assertEquals(admin.accountId(),d.row().ot().processedBy());assertEquals(admin.accountId(),d.row().ot().confirmedBy());assertTrue(d.audit().stream().anyMatch(a->a.action().equals("OT_APPROVE")));assertTrue(d.audit().stream().anyMatch(a->a.action().equals("OT_CONFIRM")));});}
    @Test void sameAdminCannotConfirmEmployeeOt(){rollback(()->{var o=service.register(employee,body(-1,20,21));action(admin,o.overtimeId(),"approve");actual(o.overtimeId(),o.requestedStart(),o.requestedEnd());assertThrows(ResponseStatusException.class,()->action(admin,o.overtimeId(),"confirm"));});}
    @Test void hrConfirmationMustBeInScopeAndIndependent(){rollback(()->{scopeHr();var o=service.register(employee,body(-1,20,21));action(hr,o.overtimeId(),"approve");actual(o.overtimeId(),o.requestedStart(),o.requestedEnd());assertThrows(ResponseStatusException.class,()->action(hr,o.overtimeId(),"confirm"));});rollback(()->{scopeHr();var o=service.register(employee,body(-1,20,21));action(admin,o.overtimeId(),"approve");actual(o.overtimeId(),o.requestedStart(),o.requestedEnd());action(hr,o.overtimeId(),"confirm");assertEquals(60L,service.detail(admin,o.overtimeId()).row().validMinutes());});}
    @Test void retroactiveDeadlineUsesEndDateNotStartDate(){rollback(()->{var o=service.register(employee,new Register(day(-4).atTime(23,30),day(-3).atTime(0,30),"OT qua ngày trong hạn",List.of(),""));assertNotNull(o);});}
    @Test void projectedNetIncludesDetailedBreaksAcrossMidnight(){rollback(()->{var start=day(1).atTime(22,0);var end=day(2).atTime(4,0);var rests=List.of(new BreakInput(day(1).atTime(23,0),day(1).atTime(23,30)),new BreakInput(day(2).atTime(1,0),day(2).atTime(1,30)));var o=service.register(employee,new Register(start,end,"OT qua ngày",rests,""));var d=service.detail(admin,o.overtimeId());assertEquals(300L,d.row().requestedMinutes());assertEquals(90L,d.days().get(0).requestedMinutes());assertEquals(210L,d.days().get(1).requestedMinutes());});}
    void schedule(){long sid=db.queryForObject("INSERT dbo.work_schedules(employee_id,work_date,planned_start,planned_end,planned_break_minutes,break_detail_status,note,created_by) OUTPUT INSERTED.schedule_id VALUES(?,?,?,?,60,'VERIFIED',N'ROLLBACK-ONLY OT test',?)",Long.class,employee.employeeId(),day(1),day(1).atTime(9,0),day(1).atTime(18,0),admin.accountId());db.update("INSERT dbo.work_schedule_breaks(schedule_id,break_start,break_end) VALUES(?,?,?)",sid,day(1).atTime(13,0),day(1).atTime(14,0));}
    @Test void netTwelveHoursAcceptedWhenGrossExceedsTwelve(){rollback(()->{schedule();var o=service.register(employee,new Register(day(1).atTime(18,0),day(1).atTime(23,30),"OT sau ca",List.of(new BreakInput(day(1).atTime(20,0),day(1).atTime(21,30))),""));assertEquals(240L,service.detail(admin,o.overtimeId()).row().requestedMinutes());});}
    @Test void netThirteenHoursIsRejected(){rollback(()->{schedule();assertThrows(ResponseStatusException.class,()->service.register(employee,body(1,18,23)));});}
    @Test void overlapIsRejected(){rollback(()->{service.register(employee,body(1,20,22));assertThrows(ResponseStatusException.class,()->service.register(employee,body(1,21,23)));});}
    @Test void approvedCancellationUsesSeparateRequestAndRetainsParentUntilDecision(){rollback(()->{var o=service.register(employee,body(1,20,21));action(admin,o.overtimeId(),"approve");long request=service.requestCancellation(employee,o.overtimeId(),version(employee,o.overtimeId()),"Không thực hiện nữa");assertEquals("DA_DUYET",core.get(admin,o.overtimeId()).request().status());service.decideRequest(admin,request,true,null,List.of());assertEquals("DA_HUY",core.get(admin,o.overtimeId()).request().status());});}
    @Test void pendingCancellationCannotBeSubmittedTwice(){rollback(()->{var o=service.register(employee,body(1,20,21));action(admin,o.overtimeId(),"approve");service.requestCancellation(employee,o.overtimeId(),version(employee,o.overtimeId()),"Lý do hủy");assertThrows(ResponseStatusException.class,()->service.requestCancellation(employee,o.overtimeId(),version(employee,o.overtimeId()),"Lần hai"));});}
    @Test void overflowRequiresApprovalThenIndependentConfirmation(){rollback(()->{scopeHr();var o=service.register(employee,body(-1,20,21));action(admin,o.overtimeId(),"approve");actual(o.overtimeId(),o.requestedStart(),day(-1).atTime(22,0));long id=service.requestOverflow(employee,o.overtimeId(),version(employee,o.overtimeId()),"Làm thêm công việc",List.of(new OvertimeRequestWorkflowService.Window(day(-1),day(-1).atTime(21,0),day(-1).atTime(22,0))));var interval=workflows.intervals(admin,id).get(0);service.decideRequest(admin,id,true,null,List.of(new OvertimeRequestWorkflowService.DecisionWindow(((Number)interval.get("interval_id")).longValue(),day(-1).atTime(21,0),day(-1).atTime(22,0))));action(hr,o.overtimeId(),"confirm");assertEquals(120L,service.detail(admin,o.overtimeId()).row().validMinutes());});}
    @Test void staleVersionCannotOverwriteDecision(){rollback(()->{var o=service.register(employee,body(1,20,21));String version=version(admin,o.overtimeId());action(admin,o.overtimeId(),"approve");assertThrows(ResponseStatusException.class,()->service.action(admin,o.overtimeId(),"reject",new OvertimeWorkspaceService.Mutation(version,"Từ chối",null)));});}
    @Test void rejectionPreservesReasonAndActor(){rollback(()->{var o=service.register(employee,body(1,20,21));action(admin,o.overtimeId(),"reject");var d=service.detail(admin,o.overtimeId());assertEquals("TU_CHOI",d.row().ot().status());assertEquals(admin.username(),d.row().approver());assertEquals("Đã kiểm tra",d.row().ot().rejectionReason());});}
    @Test void lateSubmissionAndPayrollLockAreRejected(){rollback(()->{assertThrows(ResponseStatusException.class,()->service.register(employee,body(-4,20,21)));});rollback(()->{var date=db.queryForObject("SELECT TOP(1) p.period_end FROM dbo.payroll_periods p JOIN dbo.payroll_batches b ON b.period_id=p.period_id WHERE b.status='DA_CHOT' ORDER BY p.period_end DESC",LocalDate.class);assertThrows(ResponseStatusException.class,()->service.register(employee,new Register(date.atTime(20,0),date.atTime(21,0),"Kỳ khóa")));});}
    @Test void cancellationAndAuditRollbackTogether(){rollback(()->{var o=service.register(employee,body(1,20,21));action(admin,o.overtimeId(),"approve");long id=service.requestCancellation(employee,o.overtimeId(),version(employee,o.overtimeId()),"Hủy OT");var failing=spy(db);doThrow(new IllegalStateException("Injected audit failure")).when(failing).update(startsWith("INSERT dbo.audit_logs"),any(Object[].class));var badWorkflow=proxy(new OvertimeRequestWorkflowService(failing,perms));var bad=proxy(new OvertimeWorkspaceService(db,perms,core,badWorkflow,recognition,ledger,clock));var nested=new TransactionTemplate(manager);nested.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);assertThrows(IllegalStateException.class,()->nested.executeWithoutResult(status->bad.decideRequest(admin,id,true,null,List.of())));assertEquals("DA_DUYET",core.get(admin,o.overtimeId()).request().status());assertEquals("CHO_DUYET",db.queryForObject("SELECT status FROM dbo.employee_requests WHERE request_id=?",String.class,id));});}
    @Test void liveInboxAndLegacyReadRemainUsable(){rollback(()->{assertNotNull(service.search(admin,filter(false)).stats());assertNotNull(service.inbox(admin,false,day(-30),day(30),null,null,0));});}
    @Test void soleAdminExceptionIsNotAppliedWhenAnotherAdminExists(){rollback(()->{String name="OT-ROLLBACK-"+UUID.randomUUID().toString().substring(0,10);db.update("INSERT dbo.employees(employee_code,full_name,hire_date) VALUES(?,?,?)",name,name,LocalDate.of(2020,1,1));long extraEmployee=db.queryForObject("SELECT employee_id FROM dbo.employees WHERE employee_code=?",Long.class,name);db.update("INSERT dbo.accounts(employee_id,role_id,username,password_hash,is_active) SELECT ?,role_id,?,REPLICATE('x',60),1 FROM dbo.roles WHERE role_code='ADMIN'",extraEmployee,name);var o=service.register(hr,body(-1,20,21));action(admin,o.overtimeId(),"approve");actual(o.overtimeId(),o.requestedStart(),o.requestedEnd());assertThrows(ResponseStatusException.class,()->action(admin,o.overtimeId(),"confirm"));});}
    @Test void directCancellationWithoutPendingRequestRemainsDatabaseBlocked(){rollback(()->{var o=service.register(employee,body(1,20,21));action(admin,o.overtimeId(),"approve");assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE dbo.overtime_requests SET status='DA_HUY' WHERE overtime_id=?",o.overtimeId()));});}
    @Test void cancellationInboxShowsOnlyAuthorizedRequests(){rollback(()->{var o=service.register(employee,body(1,20,21));action(admin,o.overtimeId(),"approve");long id=service.requestCancellation(employee,o.overtimeId(),version(employee,o.overtimeId()),"Không còn nhu cầu");assertTrue(service.inbox(admin,false,day(1),day(1),"HUY_OT","CHO_DUYET",0).items().stream().anyMatch(r->r.requestId()==id&&r.canDecide()));assertTrue(service.inbox(employee,true,day(1),day(1),null,null,0).items().stream().anyMatch(r->r.requestId()==id&&!r.canDecide()));});}
    @Test void legacyMissingRestIsNotCountedAsValidOrDoubleCountedAsTwoRequests(){rollback(()->{String code="OT-LEGACY-"+UUID.randomUUID().toString().substring(0,10);db.update("""
      INSERT dbo.overtime_requests(employee_id,request_code,requested_start,requested_end,reason,submitted_at,status,processed_by,processed_at,
       actual_start,actual_end,actual_break_minutes,confirmed_by,confirmed_at)
      VALUES(?,?,?,?,N'ROLLBACK-ONLY missing rest',DATEADD(minute,-1,SYSUTCDATETIME()),'DA_DUYET',?,SYSUTCDATETIME(),?,?,15,?,SYSUTCDATETIME())
      """,employee.employeeId(),code,day(-1).atTime(20,0),day(-1).atTime(21,0),admin.accountId(),day(-1).atTime(20,0),day(-1).atTime(21,0),admin.accountId());var result=service.employees(admin,new OvertimeWorkspaceService.Filter(false,day(-1),day(-1),null,null,null,null,null,employee.employeeId(),0));assertEquals(1,result.items().get(0).unresolved());assertEquals(0,result.items().get(0).validMinutes());assertEquals(1,result.stats().unresolved());});}
}
